// 根据标题获取所属分组
function getKnowledgeGroup(title) {
  for (const group in KNOWLEDGE_INDEX.groups) {
    if (KNOWLEDGE_INDEX.groups[group].some(item => item.title === title)) {
      return group;
    }
  }
  return null;
}
